import struct,collections
p=open('scratch/t88/out2/_p_server_45.bin','rb').read()
sb=open('scratch/t88/out2/_starts.bin','rb').read()
st=struct.unpack('<%dI'%(len(sb)//4),sb); n=len(st)-1
rows=[]
for i in range(n):
    a=st[i]; b=st[i+1]; nl=struct.unpack_from('<I',p,a+37)[0]
    rows.append((a, a+41+nl, b))
print('rows',len(rows))
print('== prefix bytes 0..36: constant-value offsets ==')
for o in range(37):
    c=collections.Counter(p[s+o] for s,u,e in rows)
    if len(c)<=8:
        print(' pre %2d d=%d %s'%(o,len(c),[(hex(k),v) for k,v in c.most_common(4)]))
print('== suffix field bytes 0..25 ==')
for o in range(26):
    c=collections.Counter(p[u+o] for s,u,e in rows)
    if len(c)<=8:
        print(' suf %2d d=%d %s'%(o,len(c),[(hex(k),v) for k,v in c.most_common(4)]))
print('== search 0x2d(45) constant ==')
for o in range(37):
    if all(p[s+o]==0x2d for s,u,e in rows): print(' pre',o,'==0x2d')
for o in range(26):
    if all(p[u+o]==0x2d for s,u,e in rows): print(' suf',o,'==0x2d')
"

